import { useState } from "react";

export default function App() {
  const [loggedIn, setLoggedIn] = useState(false);
  return (
    <div>
      {loggedIn ? <p id="msg">Logged in</p> : <p id="msg">Logged out</p>}
      <button onClick={() => setLoggedIn(!loggedIn)}>Đổi</button>
    </div>
  );
}

